const sourceFiles=['app/experience/model.ts','app/experience/enterprise-contract.ts','app/experience/auth-contract.ts','app/experience/security-contract.ts'];
const prepare= name=>{const src=fs.readFileSync(path.join(root,'app/experience',name+'.ts'),'utf8').replace(/from '\.\/([^']+)'/g,"from './$1.mjs'");const f=path.join(tmp,name+'.mjs');fs.writeFileSync(f,ts.transpileModule(src,{compilerOptions:{module:ts.ModuleKind.ES2022,target:ts.ScriptTarget.ES2022}}).outputText);return f;};
['model','enterprise-contract','security-contract','auth-contract'].forEach(prepare);
const load=name=>import(pathToFileURL(path.join(tmp,name+'.mjs')));
const [model,s,a]=await Promise.all([load('model'),load('security-contract'),load('auth-contract')]);
const escapeId=value=>String(value).toUpperCase().replace(/[^A-Z0-9]+/g,'_').replace(/^_|_$/g,'');
const domainFor=m=>m.family;
const sensitiveField=f=>/password|secret|token|bank|account|salary|amount|pay|gross|net|deduction|statutory|address|phone|email|identity|confidential|case note|owner|commission|rent|arrears|profit|roi|gps|location/i.test(f);
