const actorFor=m=>m.roles.includes('Owner')?'Owner / authorized administrator':m.roles.includes('Manager')?'Manager / assigned reviewer':'Employee / assigned operator';
const statusFor=m=>m.stages?.length?m.stages.join(' → '):'Available';
const opRows=[];
const addOp=(id,domain,purpose,rw,input,output,auth,scope,fields,validation,rule,audit,offline,side,error)=>opRows.push([id,domain,purpose,rw,input,output,auth,'Current permitted company',scope,fields,validation,rule,audit,offline,unknown,side,error]);
const moduleOps=new Map();
for(const m of model.modules){
 const base=escapeId(m.id),ids=[];
 const add=(suffix,purpose,rw,input,output,auth=actorFor(m),fields=m.fields.join('|'),validation='Authorization, tenant and revision validation',rule='Assignment, field and workflow guards',audit=`${base}_${suffix}`,offline='Read-only local fixture')=>{const id=`${base}_${suffix}`;ids.push(id);addOp(id,domainFor(m),purpose,rw,input,output,auth,scopeFor(m),fields,validation,rule,audit,offline,'No production side effect in Site lab','Neutral error; do not disclose missing or unauthorized resource');};
 add('LIST','List authorized records','READ',`Module ${m.id}; filters; cursor`,`Authorized ${m.title} rows`,'Assigned role projection');
 add('READ','Read one authorized record','READ','Opaque record id','Authorized field projection');
 if(!['archive','integrations','resources','session-analytics'].includes(m.kind))add('CREATE','Create a scoped draft record','WRITE','Validated fields; idempotency key','Draft record revision');
 if(!['archive','integrations','resources','session-analytics'].includes(m.kind))add('UPDATE','Update authorized fields','WRITE','Record id; expected revision; patch','New record revision');
 if((m.stages||[]).length>1)add('TRANSITION','Move through guarded states','WRITE','Record id; target state; reason; evidence','Transition result and event');
 if((m.stages||[]).some(s=>/Approve|Review|Decision|QC|Proof/.test(s)))add('APPROVE','Approve or return a controlled record','WRITE','Record id; decision; reason; expected revision','Decision result');
 if(!['archive','integrations','resources'].includes(m.kind))add('EXPORT','Export authorized projection','READ','Filter; columns; format','Governed file or denial', 'Explicit export capability',m.fields.join('|'),'Field/export policy validation');
 moduleOps.set(m.id,ids);
}
